@Test
final void summaryPaginationIsStableBoundedAndFiltered() {
    try (SessionRepository repository = createRepository()) {
        repository.create("session-b", MODEL, "workspace-a", NOW);
        repository.create("session-a", MODEL, "workspace-a", NOW);
        repository.create("session-c", MODEL, "workspace-b", NOW.minusSeconds(1));

        var first = repository.listSummaries(new SessionRepository.SummaryQuery(
                Optional.empty(), 1, Optional.of("workspace-a")));
        assertEquals(List.of("session-a"), first.sessions().stream()
                .map(SessionRepository.SessionSummary::sessionId).toList());
        assertTrue(first.nextCursor().isPresent());
        var second = repository.listSummaries(new SessionRepository.SummaryQuery(
                first.nextCursor(), 1, Optional.of("workspace-a")));
        assertEquals(List.of("session-b"), second.sessions().stream()
                .map(SessionRepository.SessionSummary::sessionId).toList());
        assertTrue(second.nextCursor().isEmpty());
        assertThrows(IllegalArgumentException.class, () -> repository.listSummaries(
                new SessionRepository.SummaryQuery(Optional.of("not-a-cursor"), 1, Optional.empty())));
    }
}

